def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]

    if n >= 99:
        return 'D'

    # Count opponent cooperation
    opp_c = opp.count('C')

    # Detect sustained defector: many defects overall, and defecting now
    if n >= 12:
        recent = opp[-12:]
        recent_d = recent.count('D')
        if recent_d >= 11:
            if rng.random() < 0.97:
                return 'D'
            return 'C'

    # Opponent has defected at least 3 of the last 4 -> retaliate firmly
    if n >= 4:
        last4 = opp[-4:]
        d4 = last4.count('D')
        if d4 >= 3:
            return 'D'

    # Sudden exploit: opponent defected last, we cooperated
    if last_opp == 'D' and last_me == 'C':
        # Retaliate once, but sometimes forgive to escape feuds
        if n >= 3 and opp[-2] == 'D' and opp[-3] == 'D':
            return 'D'
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    if last_opp == 'D' and last_me == 'D':
        # Mutual defection: attempt recovery with moderate probability
        run_d = 0
        for a in reversed(opp):
            if a == 'D':
                run_d += 1
            else:
                break
        if run_d >= 4:
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent cooperated last
    if last_me == 'D':
        # We just exploited them; return to cooperation most of the time
        # unless we detect they are a pushover
        if n >= 6:
            recent_c = opp[-6:].count('C')
            if recent_c >= 5 and opp_c * 2 > n:
                if rng.random() < 0.04:
                    return 'D'
        return 'C'

    # Both cooperated
    # Occasionally probe against highly cooperative opponents
    if n >= 10:
        recent = opp[-10:]
        recent_d = recent.count('D')
        if recent_d == 0:
            # Very cooperative: gentle probing late
            if n >= 55 and rng.random() < 0.03:
                return 'D'
            return 'C'
        if recent_d == 1:
            return 'C'
        if recent_d >= 3:
            return 'D'

    # Default: cooperate to build mutual reward
    return 'C'
